-- Table structure for table `device_command_back`
--

DROP TABLE IF EXISTS `device_command_back`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `device_command_back` (
  `device_command_id` int NOT NULL AUTO_INCREMENT,
  `dev_cat_id` int NOT NULL,
  `command_desc` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `command_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `param_type` int NOT NULL COMMENT '参数数量类型',
  `param_desc` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `test_data_standard_id` int DEFAULT NULL,
  `res_type` int NOT NULL DEFAULT '0' COMMENT '指令返回类型，是有数据返回，还是无数据返回',
  `timeout` double NOT NULL DEFAULT '0' COMMENT '指令超时时间',
  `paint` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否是获取图数据的标志',
  `paint_model_id` int DEFAULT NULL COMMENT '模板图形关联字段',
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `updated_by` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  PRIMARY KEY (`device_command_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2011 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `device_command_back`
--

LOCK TABLES `device_command_back` WRITE;
/*!40000 ALTER TABLE `device_command_back` DISABLE KEYS */;
